def _open(f, *a, **k):
    try:
        if _os.path.basename(str(f)) == 'config.yaml' and not _os.path.exists(f):
            mode = k.get('mode', a[0] if a else 'r')
            if 'b' in str(mode):
                return _io.BytesIO(_CONFIG_YAML)
            enc = k.get('encoding') or 'utf-8'
            return _io.StringIO(_CONFIG_YAML.decode(enc))
    except TypeError:
        pass
    return _orig_open(f, *a, **k)
_b.open = _open
