"""CAST-inspired long-only ETF research backtest.

Paper: Yu Peng, Matloob Khushi, Josiah Poon (2026), https://arxiv.org/abs/2609.14205
Research references (independent implementation, idea-level use):
  Official CAST (Apache-2.0): https://github.com/FanBroWell/CAST
  Author appendix: https://github.com/FanBroWell/CAST/blob/main/APPENDIX.md
  NASDAQ panel metadata: https://github.com/FanBroWell/CAST/blob/main/data/raw/NASDAQ.json
  Replication panel (huggingface.co dataset; reference only, not used at runtime): https://huggingface.co/datasets/CharlieYPeng/CAST-stock-panels
  Cvxportfolio (GPL-3.0): https://github.com/cvxgrp/cvxportfolio
  Cvxportfolio manual: https://github.com/cvxgrp/cvxportfolio/blob/master/docs/manual.rst
  Cvxportfolio example: https://github.com/cvxgrp/cvxportfolio/blob/master/examples/multiperiod_tcost.py
  QuantConnect tutorial: https://www.quantconnect.com/docs/v2/research-environment/applying-research/kalman-filters-and-stat-arb
  PyPI online filter API: https://pypi.org/project/pykalman/
"""


import gzip
import json
import signal
from collections import deque
from dataclasses import dataclass, replace
from hashlib import sha256
from math import comb
from pathlib import Path

import numpy as np
import pandas as pd
import yaml
from scipy.linalg import cho_factor, cho_solve
from scipy.optimize import linprog
from scipy.sparse import diags, eye, hstack, kron, vstack
from threadpoolctl import threadpool_limits


ROOT = Path(__file__).resolve().parent
SESSIONS_PER_YEAR = 252
PRICE_ADJUSTMENT = "yfinance auto_adjust=True, rebased split/distribution-adjusted Open and Close"


@dataclass(frozen=True)
class Model:
    orders: tuple[int, ...]
    horizon: int
    risk_aversion: float
    uncertainty_multiplier: float
    process_noise_multiple: float
    observation_noise_multiple: float
    volatility_halflife_sessions: int
    cross_asset: bool


@dataclass(frozen=True)
class Execution:
    signal_lag_sessions: int
    commission_bps: float
    slippage_bps: float
    max_asset_weight: float
    max_trade_weight: float

    @property
    def friction(self) -> float:
        return (self.commission_bps + self.slippage_bps) / 10_000


@dataclass(frozen=True)
class PricePanel:
    dates: pd.DatetimeIndex
    opens: np.ndarray
    closes: np.ndarray
    fetched_at: str


def validate_settings(model: Model, execution: Execution) -> None:
    if not 1 <= execution.signal_lag_sessions < model.horizon:
        raise ValueError("The positive signal lag must be shorter than the forecast horizon")
    if not model.orders or any(order not in (1, 2, 3) for order in model.orders):
        raise ValueError("Model orders must be drawn from 1, 2 and 3")
    if len(set(model.orders)) != len(model.orders):
        raise ValueError("Model orders must be distinct")
    if not (model.risk_aversion >= 0 and model.uncertainty_multiplier >= 0
            and model.process_noise_multiple > 0 and model.observation_noise_multiple > 0
            and model.volatility_halflife_sessions > 0):
        raise ValueError("Invalid uncertainty, noise or volatility settings")
    if not (0 < execution.max_asset_weight <= 1 and 0 < execution.max_trade_weight <= 1):
        raise ValueError("Weight and trade caps must be in (0, 1]")
    if not (0 <= execution.commission_bps < 10_000 and 0 <= execution.slippage_bps < 10_000):
        raise ValueError("Per-side costs must be nonnegative and below 10,000 bps")


def load_prices(symbols: list[str], start: pd.Timestamp, end: pd.Timestamp, snapshots: dict) -> PricePanel:
    key = sha256(json.dumps(["adjusted-oc-v1", symbols, str(start), str(end)]).encode()).hexdigest()[:16]
    name = f"yahoo-{key}.json.gz"
    snapshot = snapshots[name]
    payload = gzip.decompress(snapshot["gzip"])
    digest = sha256(payload).hexdigest()
    if digest != snapshot["sha256"]:
        raise ValueError(f"SHA-256 mismatch for snapshot {name}")
    data = json.loads(gzip.decompress(payload).decode("utf-8"))

    dates = pd.DatetimeIndex(data["dates"])
    if (data["symbols"] != symbols or dates.empty or dates.has_duplicates
            or not dates.is_monotonic_increasing or dates[0] != start or dates[-1] != end):
        raise ValueError("Price data must cover both requested endpoints and have unique ordered sessions")
    opens, closes = (np.asarray(data[field], dtype=float) for field in ("opens", "closes"))
    for prices in (opens, closes):
        if prices.shape != (len(dates), len(symbols)) or not np.all(np.isfinite(prices) & (prices > 0)):
            raise ValueError("Incomplete or nonpositive adjusted prices")

    input_digest = sha256(f"{name}:{digest}".encode()).hexdigest()
    metadata = {"path": "config.yaml", "key": "data.snapshots", "name": name, "sha256": digest}
    print("Data source: Yahoo Finance (finance.yahoo.com) daily Open and Close from yfinance "
          f"auto_adjust=True embedded in config under data.snapshots (decompressed sha256 {digest}). "
          "The script does not call yfinance, FRED or any host and reads no data_cache", flush=True)
    print(f"Input SHA-256: {input_digest}", flush=True)
    print(f"DATA_SHA256: {digest}", flush=True)
    print(f"MARKET_DATA_SNAPSHOT: {json.dumps(metadata)}", flush=True)

    base = closes[0].copy()
    return PricePanel(dates, opens / base, closes / base, data["fetched_at"])


class JointFilter:
    """One integrated random walk order, jointly updated across all ETFs."""

    def __init__(self, order: int, first_close: np.ndarray, process: np.ndarray, noise: np.ndarray):
        n_assets = len(first_close)
        companion = np.eye(order, k=-1)
        companion[0] = [(-1) ** i * comb(order, i + 1) for i in range(order)]
        self.transition = np.kron(np.eye(n_assets), companion)
        self.readout = np.arange(0, order * n_assets, order)
        self.process = np.zeros_like(self.transition)
        self.process[np.ix_(self.readout, self.readout)] = process
        self.noise = np.diag(noise)
        self.state = np.repeat(first_close, order)
        self.covariance = np.diag(np.repeat(noise, order))
        self.change = (self.transition - np.eye(len(self.state)))[self.readout]
        self.new_shock_variance = np.diag(process)

    def observe(self, close: np.ndarray) -> None:
        self.state = self.transition @ self.state
        predicted = self.transition @ self.covariance @ self.transition.T + self.process
        measured = predicted[self.readout]
        innovation = measured[:, self.readout] + self.noise
        gain = cho_solve(cho_factor(innovation, lower=True), measured).T
        self.state += gain @ (close - self.state[self.readout])
        corrected = predicted - gain @ measured
        self.covariance = (corrected + corrected.T) * 0.5

    def forecast(self, horizon: int) -> tuple[np.ndarray, np.ndarray]:
        state = self.state
        covariance = self.covariance
        path = []
        change_variance = []
        for _ in range(horizon):
            variance = np.sum((self.change @ covariance) * self.change, axis=1)
            change_variance.append(variance + self.new_shock_variance)
            state = self.transition @ state
            path.append(state[self.readout])
            covariance = self.transition @ covariance @ self.transition.T + self.process
        return np.stack(path), np.stack(change_variance)


class CollaborativePredictor:
    def __init__(self, log_closes: np.ndarray, calibration_index: int, model: Model):
        changes = np.diff(log_closes[:calibration_index + 1], axis=0)
        volatility = changes.std(axis=0, ddof=1)
        if np.any(volatility <= 0):
            raise ValueError("Calibration requires varying closes for every ETF")
        scaled = volatility * model.process_noise_multiple
        correlation = np.corrcoef(changes, rowvar=False) if model.cross_asset else np.eye(len(scaled))
        process = correlation * np.outer(scaled, scaled)
        noise = (volatility * model.observation_noise_multiple) ** 2
        self.filters = [JointFilter(order, log_closes[0], process, noise) for order in model.orders]
        self.horizon = model.horizon
        self.paths = deque(maxlen=model.horizon + 1)
        self.actual = deque(maxlen=model.horizon)
        self.previous_close = log_closes[0]
        self.base_variance = volatility ** 2
        self.current_variance = self.base_variance.copy()
        self.decay = 0.5 ** (1 / model.volatility_halflife_sessions)

    def update(self, close: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
        change = close - self.previous_close
        self.current_variance = self.decay * self.current_variance + (1 - self.decay) * change ** 2
        self.previous_close = close
        paths, variances = [], []
        for estimator in self.filters:
            estimator.observe(close)
            path, variance = estimator.forecast(self.horizon)
            paths.append(path)
            variances.append(variance)

        current_paths = np.stack(paths)
        self.paths.append(current_paths)
        self.actual.append(close)
        if len(self.paths) == self.paths.maxlen:
            # The oldest forecast's entire horizon has now resolved, including today's close.
            error = np.sum((self.paths[0] - np.stack(self.actual)) ** 2, axis=1) + 1e-12
            scores = -self.horizon / 2 * np.log(error)
            weights = np.exp(scores - scores.max(axis=0))
            weights /= weights.sum(axis=0)
        else:
            weights = np.full((len(self.filters), len(close)), 1.0 / len(self.filters))

        interval_changes = np.diff(current_paths, axis=1)
        weights = weights[:, None, :]
        expected = np.sum(weights * interval_changes, axis=0)
        component_variance = np.stack(variances)[:, 1:, :]
        variance = np.sum(weights * (component_variance + (interval_changes - expected) ** 2), axis=0)
        variance_multiple = np.maximum(self.current_variance / self.base_variance, 1.0)
        return expected, np.sqrt(variance * variance_multiple)


class Controller:
    """Plan long-only weights and turnover over the remaining forecast intervals."""

    def __init__(self, n_assets: int, model: Model, execution: Execution):
        self.n_assets = n_assets
        self.lag = execution.signal_lag_sessions
        self.risk = model.risk_aversion * model.uncertainty_multiplier
        n_steps = model.horizon - self.lag
        n_weights = n_steps * n_assets
        identity = eye(n_weights, format="csr")
        differences = diags([1.0, -1.0], [0, -n_assets], shape=identity.shape) if n_steps > 1 else identity
        budgets = kron(eye(n_steps), np.ones((1, n_assets)))
        self.constraints = vstack([
            hstack([differences, -identity]), hstack([-differences, -identity]),
            hstack([budgets, budgets * 0]),
        ], format="csr")
        self.limits = np.r_[np.zeros(2 * n_weights), np.ones(n_steps)]
        self.bounds = ([(0.0, execution.max_asset_weight)] * n_weights
                       + [(0.0, execution.max_trade_weight)] * n_weights)
        self.max_weight = execution.max_asset_weight
        self.max_reductions = np.arange(1, n_steps + 1)[:, None] * execution.max_trade_weight
        self.costs = np.full(n_weights, execution.friction)

    def plan(self, current_weights: np.ndarray, expected: np.ndarray, uncertainty: np.ndarray) -> np.ndarray:
        # A fill on t+lag only uses forecast increments from that forecast close onward.
        utility = expected[self.lag - 1:] - self.risk * uncertainty[self.lag - 1:]
        limits = self.limits.copy()
        limits[:self.n_assets] = current_weights
        n_weights = utility.size
        limits[n_weights:n_weights + self.n_assets] = -current_weights
        bounds = self.bounds
        excess = current_weights - self.max_reductions
        if np.any(excess > self.max_weight):
            # After an extreme gap, allow only the excess that the trade cap prevents selling.
            weight_limits = np.maximum(excess, self.max_weight)
            bounds = [(0.0, cap) for cap in weight_limits.ravel()] + bounds[n_weights:]
        solution = linprog(
            np.r_[-utility.ravel(), self.costs], A_ub=self.constraints, b_ub=limits,
            bounds=bounds, method="highs-ds", options={"time_limit": 2.0},
        )
        if not solution.success:
            raise RuntimeError(f"MPC failed: {solution.message}")
        return solution.x[:self.n_assets]


def fill_at_open(
    positions: np.ndarray, cash: float, opening_prices: np.ndarray, target: np.ndarray,
    execution: Execution,
) -> tuple[np.ndarray, float, float, int]:
    open_positions = positions * opening_prices
    opening_value = cash + open_positions.sum()
    cap = execution.max_trade_weight * opening_value
    desired = np.clip(target * opening_value - open_positions, -cap, cap)
    desired[np.abs(desired) < 1e-10 * opening_value] = 0.0
    sells = np.minimum(np.maximum(-desired, 0.0), open_positions)
    buys = np.maximum(desired, 0.0)
    commission, slippage = execution.commission_bps / 10_000, execution.slippage_bps / 10_000
    cash += sells.sum() * (1 - slippage) * (1 - commission)
    buy_price_factor = (1 + slippage) * (1 + commission)
    purchase = buys.sum() * buy_price_factor
    if purchase > cash:
        buys *= cash / purchase
    cash -= buys.sum() * buy_price_factor
    if cash < -1e-12 * opening_value:
        raise RuntimeError("Opening fills exceeded available cash")
    remaining = (open_positions - sells + buys) / opening_prices
    traded = sells + buys
    return remaining, max(cash, 0.0), traded.sum() / opening_value, int(np.count_nonzero(traded))


def run_strategy(
    opens: np.ndarray, closes: np.ndarray, calibration_index: int, first_day: int,
    model: Model, execution: Execution,
) -> np.ndarray:
    log_closes = np.log(closes)
    predictor = CollaborativePredictor(log_closes, calibration_index, model)
    controller = Controller(closes.shape[1], model, execution)
    positions = np.zeros(closes.shape[1])
    cash, previous_value = 1.0, 1.0
    pending = {}
    daily_results = []
    for day in range(1, len(closes)):
        turnover, trades = 0.0, 0
        if day in pending:
            positions, cash, turnover, trades = fill_at_open(
                positions, cash, opens[day], pending.pop(day), execution,
            )
        close_positions = positions * closes[day]
        close_value = cash + close_positions.sum()
        if day >= first_day:
            daily_results.append((close_value / previous_value - 1, turnover, trades))
        previous_value = close_value

        expected, uncertainty = predictor.update(log_closes[day])
        fill_day = day + execution.signal_lag_sessions
        if day >= calibration_index and first_day <= fill_day < len(closes):
            pending[fill_day] = controller.plan(close_positions / close_value, expected, uncertainty)
    return np.asarray(daily_results)


def buy_and_hold(opens: np.ndarray, closes: np.ndarray, execution: Execution) -> np.ndarray:
    terms = replace(execution, max_trade_weight=1.0)
    positions, cash, turnover, traded = fill_at_open(
        np.zeros(1), 1.0, opens[:1], np.ones(1), terms,
    )
    values = np.r_[1.0, cash + positions[0] * closes]
    daily_results = np.zeros((len(closes), 3))
    daily_results[:, 0] = values[1:] / values[:-1] - 1
    daily_results[0, 1:] = turnover, traded
    return daily_results


def metrics(daily_results: np.ndarray, cash_reference: np.ndarray) -> dict:
    returns, turnover, trades = daily_results.T
    growth = np.r_[1.0, np.cumprod(1 + returns)]
    annualization = np.sqrt(SESSIONS_PER_YEAR)
    vol = returns.std(ddof=1)
    excess = returns - cash_reference
    excess_vol = excess.std(ddof=1)
    return {
        "cagr": float(growth[-1] ** (SESSIONS_PER_YEAR / len(returns)) - 1),
        "ann_vol": float(vol * annualization),
        "sharpe": float(annualization * returns.mean() / vol) if vol > 0 else None,
        "sharpe_excess": float(annualization * excess.mean() / excess_vol) if excess_vol > 0 else None,
        "max_drawdown": float(np.min(growth / np.maximum.accumulate(growth) - 1)),
        "total_return": float(growth[-1] - 1),
        "turnover": float(turnover.mean() * SESSIONS_PER_YEAR),
        "n_trades": int(trades.sum()),
    }


def main() -> None:
    signal.alarm(840)
    config = yaml.safe_load((ROOT / "config.yaml").read_text(encoding="utf-8"))
    model, execution = Model(**config["model"]), Execution(**config["execution"])
    dates = {key: pd.Timestamp(value) for key, value in config["dates"].items()}
    universe, benchmark, cash_symbol = config["universe"], config["benchmark"], config["cash_reference"]
    symbols = [*universe, benchmark, cash_symbol]
    if len(universe) < 2 or len(set(symbols)) != len(symbols):
        raise ValueError("Specify distinct symbols for the universe, benchmark and cash reference")
    variants = [("official", model, execution)]
    for variant in config["robustness"]:
        variants.append((variant["label"], replace(model, **variant.get("model", {})),
                         replace(execution, **variant.get("execution", {}))))
    for _, settings, terms in variants:
        validate_settings(settings, terms)

    panel = load_prices(symbols, dates["data_start"], dates["end"], config["data"]["snapshots"])
    calibration, first, is_last = (panel.dates.get_loc(dates[key]) for key in (
        "calibration_end", "evaluation_start", "is_end",
    ))
    if not max(settings.horizon for _, settings, _ in variants) + 2 <= calibration < first < is_last < len(panel.dates) - 2:
        raise ValueError("Need a separate calibration history and at least two sessions in each report period")
    print(f"DATA_FETCHED_AT: {panel.fetched_at}", flush=True)
    print(f"PRICE_ADJUSTMENT: {PRICE_ADJUSTMENT}", flush=True)

    benchmark_dates = panel.dates[first:]
    sample_range = f"{benchmark_dates[0]:%Y-%m-%d} to {benchmark_dates[-1]:%Y-%m-%d}"
    is_length = is_last - first + 1
    cash_reference = panel.closes[first:, -1] / panel.closes[first - 1:-1, -1] - 1
    cash_reference[0] = panel.closes[first, -1] / panel.opens[first, -1] - 1
    strategy_opens, strategy_closes = panel.opens[:, :len(universe)], panel.closes[:, :len(universe)]

    print(f"ROBUSTNESS (IS ONLY, through {panel.dates[is_last]:%Y-%m-%d})", flush=True)
    for label, settings, terms in variants[1:]:
        daily = run_strategy(strategy_opens[:is_last + 1], strategy_closes[:is_last + 1],
                             calibration, first, settings, terms)
        print(f"  {label}: {json.dumps(metrics(daily, cash_reference[:is_length]), allow_nan=False)}", flush=True)

    daily = run_strategy(strategy_opens, strategy_closes, calibration, first, model, execution)
    if not np.any(daily[:, 2]):
        raise RuntimeError("No fills in the official simulation")
    benchmark_daily = buy_and_hold(panel.opens[first:, -2], panel.closes[first:, -2], execution)
    periods = {"is": slice(None, is_length), "oos": slice(is_length, None), "full": slice(None)}
    strategy_results = {key: metrics(daily[period], cash_reference[period]) for key, period in periods.items()}
    benchmark_results = {key: metrics(benchmark_daily[period], cash_reference[period])
                         for key, period in periods.items()}
    print(f"PARAM_COMBOS_TRIED: {len(variants)}")
    print(f"Excess Sharpe reference: {cash_symbol} total return")
    for key, period in periods.items():
        period_dates = benchmark_dates[period]
        print(f"{key.upper()} {period_dates[0]:%Y-%m-%d} to {period_dates[-1]:%Y-%m-%d}")
        print(f"  CAST: {json.dumps(strategy_results[key], allow_nan=False)}")
        print(f"  {benchmark} buy-and-hold: {json.dumps(benchmark_results[key], allow_nan=False)}")
    print("LOOK_AHEAD_CHECK: close-to-later-open lag; close-only inputs; first-close rebasing; "
          "pre-sample calibration and IS-only alternatives")
    results = {"strategy": config["strategy"], "data_range": sample_range, **strategy_results,
               "benchmark": {"name": f"{benchmark} buy-and-hold", **benchmark_results}}
    print("RESULTS_JSON: " + json.dumps(results, allow_nan=False), flush=True)
    signal.alarm(0)


if __name__ == "__main__":
    with threadpool_limits(limits=1, user_api="blas"):
        main()
